CREATE TRIGGER assessments_terminal_frozen
BEFORE UPDATE ON assessments
WHEN OLD.state IN ('complete', 'complete_with_issues', 'failed', 'canceled')
BEGIN
  SELECT RAISE(ABORT, 'assessments: a terminal assessment cannot change');
END;
