CREATE TRIGGER assessments_state_transitions
BEFORE UPDATE OF state ON assessments
WHEN NEW.state IS NOT OLD.state AND OLD.state NOT IN ('complete', 'complete_with_issues', 'failed', 'canceled') AND NOT (
    (OLD.state = 'queued' AND NEW.state IN ('acquiring', 'finalizing', 'canceled', 'failed')) OR
    (OLD.state = 'acquiring' AND NEW.state IN ('analyzing', 'finalizing', 'canceled', 'failed')) OR
    (OLD.state = 'analyzing' AND NEW.state IN ('finalizing', 'canceled', 'failed')) OR
    (OLD.state = 'finalizing' AND NEW.state IN ('complete', 'complete_with_issues', 'failed', 'canceled'))
  )
BEGIN
  SELECT RAISE(ABORT, 'assessments: state transition is not allowed');
END;
